const normN=v=>{v=String(v??'').trim();return /^\d{6,9}$/.test(v)?v.padStart(10,'0'):v};
function impCheck(){const I=S.imp,t=I.t,bad=[],seen={},kk=kls();I.rows.forEach((r,i)=>{const e=[],w=[],raw=String(r.nisn??'').trim(),n=normN(raw),k=I.mode=='semua'?String(r.kelas||'').trim():I.kelas;
if(!n)e.push('NISN kosong');else if(!/^\d{10}$/.test(n))w.push('NISN bukan 10 digit (tetap diimpor)');else if(n!=raw)w.push('NISN dilengkapi nol di depan: '+n);
if(!k)e.push('Kelas kosong (isi kolom kelas, atau ubah Mode ke “Satu kelas”)');
if(S.role=='guru'&&t!='siswa'&&k&&!(t=='nilai'?canN(k):canH(k)))e.push('Bukan kelas yang Anda ampu');
if(n){const key=n+'|'+(r.sem||'')+'|'+(t=='ekskul'?String(r.ekskul||'').trim().toLowerCase():'');if(seen[key]!=null)e.push('NISN dobel dalam file (baris '+(seen[key]+2)+')');else seen[key]=i}
if(t=='siswa'){if(!r.nama)e.push('Nama kosong');if(r.nik&&!/^\d{16}$/.test(String(r.nik)))w.push('NIK bukan 16 digit');if(n&&db.siswa.some(s=>s.nisn==n&&s.ta==S.ta))w.push(I.dup=='skip'?'Sudah ada, akan dilewati':'Sudah ada, akan ditimpa')}
else if(n&&!db.siswa.some(s=>s.nisn==n&&s.ta==S.ta))e.push('NISN belum terdaftar di '+S.ta);
if(t=='nilai')SC.forEach(c=>{const v=r[c];if(v===''||v==null||String(v).trim().toUpperCase()=='X')return;if(isNaN(+v)||+v<0||+v>100)w.push('Nilai '+(SN[c]||c)+' tidak valid, dikosongkan')});
if(t=='hadir')['sakit','izin','alpa'].forEach(c=>{if(r[c]!==''&&r[c]!=null&&(isNaN(+r[c])||+r[c]<0))w.push(c+' bukan angka, dianggap 0')});
if(t=='ekskul'&&!String(r.ekskul||'').trim())e.push('Nama ekstrakurikuler kosong');
if(e.length||w.length)bad.push({i,n:i+2,nisn:raw,e,w})});return bad}
const impBox=()=>{const I=S.imp,bad=impCheck(),er=bad.filter(b=>b.e.length),wa=bad.filter(b=>!b.e.length&&b.w.length);return`<div class="bar">${bd((I.rows.length-er.length)+' baris siap diimpor','ok')}${er.length?bd(er.length+' baris error (dilewati)','e'):''}${wa.length?bd(wa.length+' peringatan','w'):''}${bad.length?B('exbad','','⬇ Unduh laporan masalah'):''}</div>${bad.length?tbl(['Baris Excel','NISN','Masalah'],bad.slice(0,15).map(b=>[b.n,E(b.nisn),[...b.e.map(x=>'<span style="color:var(--er)">✖ '+E(x)+'</span>'),...b.w.map(x=>'⚠ '+E(x))].join('<br>')])):''}${bad.length>15?`<p class="sub">…dan ${bad.length-15} baris lain, unduh laporan untuk daftar lengkap.</p>`:''}`};
