const ck=(c,v,on,t)=>`<label style="display:flex;gap:4px;margin:0;color:#1b2430;font-size:12px"><input type="checkbox" class="${c}" value="${E(v)}" ${on?'checked':''}> ${E(t)}</label>`;
A.gedit=v=>{const g=v?db.guru.find(x=>x.id==+v):{mapel:[],kelasAjar:[],wali:'',jk:'L'};S.ge=v?+v:0;mod(`<div class="mbox w2"><h3>${v?'Edit':'Tambah'} Guru</h3><p class="sub">Lengkapi data guru lalu tentukan perannya.</p><div class="fl">${GF.map(f=>gfld(f,g)).join('')}</div><h5 style="margin:14px 0 6px;color:var(--p)">Peran guru (boleh dua-duanya)</h5><div class="card" style="margin:0 0 8px"><label style="display:flex;gap:6px;color:#1b2430;font-size:13px"><input type="checkbox" id="g_ismp" ${g.mapel.length?'checked':''}> Guru mapel — bisa mengedit nilai mapelnya</label><label style="margin-top:8px">Mata pelajaran diampu</label><div class="bar">${MP.map(m=>ck('gm',m[0],g.mapel.includes(m[0]),m[1])).join('')}</div><label>Mengajar di kelas</label><div class="bar">${kls().map(k=>ck('gk',k,g.kelasAjar.includes(k),k)).join('')}</div></div><div class="card" style="margin:0"><label style="display:flex;gap:6px;color:#1b2430;font-size:13px"><input type="checkbox" id="g_iswali" ${g.wali?'checked':''}> Wali kelas — bisa menaikkan kelas siswa di kelasnya</label><select id="g_wali" style="margin-top:6px">${opt(kls(),g.wali)}</select></div><div class="bar" style="margin:14px 0 0"><span class="sp"></span>${B('close','','Batal')}${B('gsave','','Simpan','a')}</div></div>`)};
A.gsave=()=>{const d={};GF.forEach(f=>d[f[0]]=$('#g_'+f[0]).value.trim());if(!d.nama)return toast('Nama guru wajib diisi');const mp=$('#g_ismp').checked,w=$('#g_iswali').checked,q=s=>[...document.querySelectorAll(s)].map(e=>e.value);d.mapel=mp?q('.gm:checked'):[];d.kelasAjar=mp?q('.gk:checked'):[];d.wali=w?$('#g_wali').value:'';if(!mp&&!w)return toast('Pilih minimal satu peran');if(mp&&(!d.mapel.length||!d.kelasAjar.length))return toast('Pilih mapel dan kelas yang diajar');const bt=d.wali&&db.guru.find(x=>x.wali==d.wali&&x.id!=S.ge);if(bt)return toast('Kelas '+d.wali+' sudah punya wali: '+bt.nama);if(S.ge)Object.assign(db.guru.find(x=>x.id==S.ge),d);else db.guru.push({id:id++,...d});L('Simpan guru '+d.nama);close();R();toast('Data guru tersimpan')};
const guruPg=()=>`<h2>Data Guru</h2><p class="sub">${db.guru.length} guru · ${db.guru.filter(g=>g.mapel.length).length} guru mapel · ${db.guru.filter(g=>g.wali).length} wali kelas</p><div class="note">Guru mapel hanya bisa mengedit nilai mapelnya di kelas yang diajar. Wali kelas bisa menaikkan kelas siswa di kelasnya sendiri dan mengelola kehadiran & ekskul kelasnya. Satu guru boleh punya kedua peran. Coba login sebagai Guru di bar atas.</div><div class="card"><div class="bar"><b>Daftar guru</b><span class="sp"></span>${B('gedit','','+ Tambah guru','a')}</div>${tbl(['Nama','NIP','NUPTK','Status','Peran','Mapel','Mengajar di','Wali kelas','HP','Aksi'],db.guru.map(g=>[`<b>${E(g.nama)}</b>`,E(g.nip),E(g.nuptk),E(g.status),(g.mapel.length?bd('Guru Mapel','ok'):'')+' '+(g.wali?bd('Wali Kelas','w'):''),E(mpn(g.mapel)),E(g.kelasAjar.join(', ')||'-'),E(g.wali||'-'),E(g.hp),B('gedit',g.id,'Edit')+' '+B('gdel',g.id,'🗑','x')]))}</div>`;
const gdashPg=()=>{const g=gr();return`<h2>Beranda Guru</h2><p class="sub">${peran(g)}</p><div class="hero2"><div><span class="pl2">● TAHUN AJARAN ${S.ta} ${String(CUR.sem).toUpperCase()} • KURIKULUM MERDEKA</span><h1>Selamat Datang, ${g.jk=='P'?'Ibu ':g.jk=='L'?'Bapak ':''}${E(g.nama)}</h1><p>Portal Akademik Guru • ${E(S.school)}. Kelola agenda pembelajaran, absensi digital, dan validasi buku induk.</p><div class="chs">${g.mapel.length?`<span>▣ Guru ${E(mpn(g.mapel))}</span>`:''}${g.wali?`<span>★ Wali Kelas ${E(g.wali)}</span>`:''}</div></div><div class="dt"><small>Hari ini</small><b>${new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</b></div></div><div class="g g2">${g.mapel.length?`<div class="card"><h3>📝 Guru Mapel</h3><div class="row"><span>Mapel</span><b>${E(mpn(g.mapel))}</b></div><div class="row"><span>Kelas diajar</span><b>${E(g.kelasAjar.join(', '))}</b></div><div class="bar" style="margin-top:10px">${B('nav','nm','Input nilai mapel','a')}</div></div>`:''}${g.wali?`<div class="card"><h3>👩‍🏫 Wali Kelas ${E(g.wali)}</h3><div class="row"><span>Siswa aktif</span><b>${db.siswa.filter(s=>s.ta==S.ta&&s.kelas==g.wali&&s.status=='Aktif').length}</b></div><div class="bar" style="margin-top:10px">${B('nav','naik','Kenaikan kelas','a')}</div></div>`:''}</div>`};
function nmPg(){const g=gr(),N=S.nm=S.nm||{k:g.kelasAjar[0],sem:'Ganjil'},ms=MP.filter(m=>g.mapel.includes(m[0]));if(!g.kelasAjar.includes(N.k))N.k=g.kelasAjar[0];const l=db.siswa.filter(s=>s.ta==S.ta&&s.kelas==N.k&&s.status=='Aktif'),nv=s=>db.nilai.find(x=>x.nisn==s.nisn&&x.ta==S.ta&&x.sem==N.sem)||{};return`<h2>Input Nilai Mapel</h2><p class="sub">${E(ms.map(m=>m[1]).join(', '))} · hanya mapel dan kelas yang Anda ajar</p><div class="card"><div class="bar"><div><label>Kelas</label><select data-c="nm" data-k="k">${opt(g.kelasAjar,N.k)}</select></div><div><label>Semester</label><select data-c="nm" data-k="sem">${opt(SEM,N.sem)}</select></div><span class="sp"></span>${B('nmsave','','Simpan nilai','a')}</div>${tbl(['Nama','NISN',...ms.map(m=>m[1])],l.map(s=>[`<b>${E(s.nama)}</b>`,s.nisn,...ms.map(m=>`<input type="number" min="0" max="100" style="width:90px" data-nm="${s.nisn}|${m[0]}" value="${nv(s)[m[0]]??''}">`)]))}</div>`}
A.nmsave=()=>{const g=gr(),N=S.nm;let n=0;{const bx=[...document.querySelectorAll('[data-nm]')].filter(e=>e.value!==''&&(isNaN(e.value)||+e.value<0||+e.value>100));document.querySelectorAll('[data-nm]').forEach(e=>e.style.borderColor='');if(bx.length){bx.forEach(e=>e.style.borderColor='var(--er)');return toast(bx.length+' nilai harus angka 0–100')}}document.querySelectorAll('[data-nm]').forEach(e=>{if(e.value==='')return;const[nisn,c]=e.dataset.nm.split('|');if(!g.mapel.includes(c))return;const v=Math.max(0,Math.min(100,+e.value||0));let r=db.nilai.find(x=>x.nisn==nisn&&x.ta==S.ta&&x.sem==N.sem);if(!r){r={nisn,ta:S.ta,kelas:N.k,sem:N.sem};db.nilai.push(r)}r[c]=v;n++});L('Input nilai '+N.k+' '+N.sem+' ('+n+' nilai)');R();toast(n+' nilai tersimpan')};
function init(){const dm=!S.auth||S.auth.demo;$('#rsw').style.display=dm?'':'none';$('#au').innerHTML=S.auth?'👤 '+E(S.auth.name)+' · <a data-a="logout" style="cursor:pointer;text-decoration:underline">Keluar</a>':'';$('#gq').style.display=S.role=='siswa'?'none':'';$('#gs').innerHTML=S.role=='guru'&&dm?'Guru: <select data-c="gsel">'+db.guru.map(g=>`<option value="${g.id}" ${g.id==S.gid?'selected':''}>${E(g.nama)}</option>`).join('')+'</select>':'';$('[data-c=role]').innerHTML=opt(['Admin','Guru','Siswa'],S.role[0].toUpperCase()+S.role.slice(1));$('[data-c=ta]').innerHTML=opt(S.tas,S.ta)}
function R(){init();if(S.role=='siswa'){$('#app').innerHTML=mobile();return}const nav=S.role=='admin'?ADM:gnav(),ac=n=>n==S.p||(S.p=='i:siswa'&&n=='siswa')||(S.p=='form'&&n=='form');
$('#app').innerHTML=`<div class="app"><div class="sb"><div class="logo"><img src="${JB}" alt=""><div><b>JosBook</b><small>PORTAL<br>AKADEMIK</small></div></div>${nav.map(n=>`<a class="${ac(n[0])?'on':''}" data-a="nav" data-v="${n[0]}">${ICO[n[0]]||''}<span>${n[1].replace(/^\S+\s/,'')}</span></a>`).join('')}<a class="lo" data-a="logout">${ICO.out}<span>Keluar</span></a><div class="role" data-a="umenu" data-i="${S.role=='admin'?'AS':''}"><b>${S.role=='admin'?'Admin Sekolah':E(gr().nama)}</b><span>${S.role=='admin'?'Akses penuh':peran(gr())}</span><em class="chv">⌄</em>${S.um?`<div class="um" onclick="event.stopPropagation()"><label>Tahun ajaran</label><select data-c="ta">${opt(S.tas,S.ta)}</select><button class="btn x" data-a="logout">Keluar</button></div>`:''}</div></div><div class="mn">${page()}</div></div>`}
document.addEventListener('click',e=>{const a=e.target.closest('[data-a]');if(a&&A[a.dataset.a]&&!(a.tagName=='INPUT'&&e.type!='click'))A[a.dataset.a](a.dataset.v,a)});
document.addEventListener('change',e=>{const c=e.target.dataset.c;if(c&&C[c])C[c](e.target.value,e.target)});
/* ===== Dokumen cetak sesuai PDF: sampul, register (hal. A–I), laporan capaian ===== */
const fr=(n,l,v,i)=>`<div class="fr${i?' in':''}"><span>${n}</span><span>${l}</span><span class="v">: ${E(v==null||v===''?'-':v)}</span></div>`,fh=t=>`<div class="fh">${t}</div>`,kg=v=>num(v)?String(v).replace('.',','):v,LT='abcdefgh',
PL=['Nama','Agama','Kewarganegaraan','Pendidikan Terakhir','Pekerjaan','Penghasilan per bulan','Nomor Telepon/HP','Keadaan'],AL=['Jalan','RT/RW','Desa','Kecamatan','Kabupaten','Provinsi','Kode Pos'],
par=(no,t,s,ks)=>fr(no,t,'',0).replace(/<span class="v">.*<\/span>/,'<span></span>')+ks.map((k,i)=>fr('',LT[i]+'. '+PL[i],s[k],1)).join(''),
adr=(s,ks,hp)=>ks.map((k,i)=>fr('',AL[i],s[k],1)).join('');
function reg(s){const pg=x=>`<div class="pg dc">${x}</div>`,S_=s,ph=`<div class="ph1">${(s.foto||s.foto_masuk)?`<img src="${E(s.foto||s.foto_masuk)}">`:'<span>Pas foto<br>3 × 4</span>'}</div>`;
const p1=pg(`<div class="hd"><div class="hl"><div class="ptt">I. BUKU INDUK REGISTER PESERTA DIDIK<br>KURIKULUM MERDEKA<br>${E(S.school.toUpperCase())}</div><div class="nn"><span>NOMOR INDUK : <u>${E(s.nis)}</u></span><span>NISN : <u>${E(s.nisn)}</u></span></div></div>${ph}</div>`+fh('A. KETERANGAN PESERTA DIDIK')+fr('1.','a. Nama Lengkap',s.nama)+fr('','b. Nama Panggilan',s.panggilan)+fr('2.','Jenis Kelamin',jkl(s.jk))+fr('3.','a. Tempat Lahir',s.tmp)+fr('','b. Tanggal Lahir',tgi(s.tgl))+fr('4.','Agama',s.agama)+fr('5.','Kewarganegaraan',s.kewarganegaraan)+fr('6.','Nomor Induk Kependudukan',s.nik)+fr('7.','Anak ke',s.anak_ke)+fr('8.','Jumlah Saudara Kandung',s.jml_saudara)+fr('9.','Anak Yatim/Yatim Piatu',s.yatim)+fr('10.','Bahasa Sehari-hari',s.bahasa)+fh('B. KETERANGAN TEMPAT TINGGAL')+fr('12.','Alamat','').replace(/<span class="v">.*<\/span>/,'<span></span>')+adr(s,['alamat','rt_rw','kelurahan','kecamatan','kab','prov','kodepos'])+fr('','Nomor Telepon/HP',s.hp,1)+fr('13.','Tempat Tinggal',s.tinggal)+fr('14.','Jarak ke sekolah',num(s.jarak)?kg(s.jarak)+' Kilometer':s.jarak)+fh('C. KETERANGAN KESEHATAN')+fr('15.','Golongan Darah',s.gol_darah)+fr('16.','Penyakit yang diderita',s.penyakit)+fr('17.','Kelainan Jasmani/Fisik',s.kelainan)+fr('18.','a. Tinggi Badan',num(s.tinggi)?s.tinggi+' Cm':s.tinggi)+fr('','b. Berat Badan',num(s.berat)?s.berat+' Kg':s.berat));
const p2=pg(fh('D. KETERANGAN PENDIDIKAN')+fr('19.','Pendidikan Sebelumnya','').replace(/<span class="v">.*<\/span>/,'<span></span>')+fr('','a. Sekolah Asal',s.asal,1)+fr('','b. Tanggal dan Nomor Ijazah',tgi(s.tgl_ijazah_smp)+' dan '+(s.no_ijazah_smp||'-'),1)+fr('','c. Lama Belajar',num(s.lama)?s.lama+' Tahun':s.lama,1)+fr('20.','Pindahan',s.masuk)+fr('','a. Dari Sekolah',s.sekolah_pindah,1)+fr('','b. Alasan',s.alasan_pindah,1)+fr('21.','Diterima di sekolah ini','').replace(/<span class="v">.*<\/span>/,'<span></span>')+fr('','a. Di kelas',s.kelas_masuk,1)+fr('','b. Rombel Kelas ke',(s.kelas_masuk||'')+'-'+(s.rombel_masuk||''),1)+fr('','c. Tanggal',tgi(s.tgl_masuk),1)+fh('E. KETERANGAN ORANG TUA KANDUNG')+par('22.','Ayah Kandung',s,['ayah','agama_ayah','wn_ayah','pend_ayah','kerja_ayah','gaji_ayah','hp_ayah','ket_ayah'])+par('23.','Ibu Kandung',s,['ibu','agama_ibu','wn_ibu','pend_ibu','kerja_ibu','gaji_ibu','hp_ibu','ket_ibu'])+fr('24.','Alamat Orang Tua','').replace(/<span class="v">.*<\/span>/,'<span></span>')+adr(s,['al_jalan','al_rt','al_desa','al_kec','al_kab','al_prov','al_pos']));
const p3=pg(fh('F. KETERANGAN WALI')+par('25.','Wali',s,['wali','agama_wali','wn_wali','pend_wali','kerja_wali','gaji_wali','hp_wali'])+fr('','h. Alamat','',1).replace(/<span class="v">.*<\/span>/,'<span></span>')+adr(s,['alw_jalan','alw_rt','alw_desa','alw_kec','alw_kab','alw_prov','alw_pos'])+fh('G. MENINGGALKAN SEKOLAH')+fr('26.','Meninggalkan Sekolah','').replace(/<span class="v">.*<\/span>/,'<span></span>')+fr('','a. Tanggal',tgi(s.tgl_keluar),1)+fr('','b. Alasan',s.alasan_keluar||s.status,1)+fr('27.','Tamat Belajar/Lulus','').replace(/<span class="v">.*<\/span>/,'<span></span>')+fr('','a. Tanggal SKL',tgi(s.tgl_keluar),1)+fr('','b. Nomor SKL',s.no_skl,1)+fr('','c. Tanggal Ijazah',tgi(s.tgl_ijazah_sma),1)+fr('','d. Nomor Ijazah',s.no_ijazah_sma,1)+fr('','e. Nomor Transkrip Nilai',s.no_transkrip,1)+fh('H. KETERANGAN SETELAH SELESAI PENDIDIKAN')+fr('28.','Melanjutkan Studi / Bekerja',s.lanjut)+fh('I. CATATAN')+`<div style="border-bottom:1px solid #000;min-height:20px">${E(s.catatan&&s.catatan!='-'?s.catatan:'')}</div>`+xsec(s));
return p1+p2+p3}
function lap(s,ta,o){o=o||{nilai:1,hadir:1,ekskul:1,naik:1};const ms=!o.sem||o.sem=='Semua'?SEM:[o.sem],nc=ms.length,sl=m=>SEM.indexOf(m)+1,r=db.siswa.find(x=>x.nisn==s.nisn&&x.ta==ta)||s,k=r.kelas,xii=tk(k)=='XII',ly=LYT[tk(k)]||LYT.X,g=(t,m)=>db[t].find(x=>x.nisn==s.nisn&&x.ta==ta&&x.sem==m)||{},N=ms.map(m=>g('nilai',m)),H=ms.map(m=>g('hadir',m)),KK=S.sc.kktp;let miss=0;
const rows=ly.map(([t,cs])=>`<tr class="gh"><td colspan="${3+nc}">${t}</td></tr>`+cs.map((c,i)=>`<tr><td>${i+1}</td><td class="l">${SN[c]}</td><td>${KK}</td>`+N.map(x=>num(x[c])?`<td>${x[c]}</td>`:(miss=1,'<td>X</td>')).join('')+'</tr>').join('')).join(''),
av=N.map(x=>SC.some(c=>num(x[c]))?f2(avg(x)):'-'),ek=[...new Set(db.ekskul.filter(x=>x.nisn==s.nisn&&x.ta==ta&&ms.includes(x.sem)).map(x=>x.ekskul))],ep=(n,m)=>(db.ekskul.find(x=>x.nisn==s.nisn&&x.ta==ta&&x.sem==m&&x.ekskul==n)||{}).predikat||'-',hd=c=>H.map(x=>`<td>${x[c]??0} hari</td>`).join(''),ch=xii?['LULUS','TIDAK LULUS']:['NAIK','TIDAK NAIK'],pick=r.ket_naik||ch[0],
idn=`<div class="fh">A. IDENTITAS PESERTA DIDIK</div>`+fr('','Nama Peserta Didik',s.nama,1)+fr('','NIS',s.nis,1)+fr('','NISN',s.nisn,1);
const nilaiH=o.nilai?`${fh('B. INTRAKURIKULER')}<table class="lt"><tr><th rowspan="2">No</th><th rowspan="2">Mata Pelajaran</th><th rowspan="2">KKTP</th><th colspan="${nc}">Kelas ${E(k)}</th></tr><tr>${ms.map(m=>`<th>Semester ${sl(m)}</th>`).join('')}</tr>${rows}<tr><td colspan="3"><b>Rata-rata</b></td>${av.map(x=>`<td><b>${x}</b></td>`).join('')}</tr></table>${miss?'<div>Keterangan:<br>&nbsp;X : Tidak diajarkan pada semester tersebut</div>':''}`:'',
kokH=o.hadir?`${fh('C. KOKURIKULER')}${H.map((x,i)=>`<div class="kk"><div>No &nbsp; Deskripsi Nilai Kokurikuler</div><div>${sl(ms[i])} &nbsp; ${E(x.kokur||'-')}</div></div>`).join('')}`:'',
ekH=o.ekskul?`${fh('D. EKSTRAKURIKULER')}<table class="lt"><tr><th>No</th><th>Ekstrakurikuler</th>${ms.map(m=>`<th>Semester ${sl(m)}</th>`).join('')}</tr>${ek.map((n,i)=>`<tr><td>${i+1}</td><td class="l">${E(n)}</td>${ms.map(m=>`<td>${E(ep(n,m))}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${2+nc}">-</td></tr>`}</table>`:'',
hdH=o.hadir?`${fh('E. KETIDAKHADIRAN')}<table class="lt"><tr><th>No</th><th>Keterangan</th>${ms.map(m=>`<th>Semester ${sl(m)}</th>`).join('')}</tr>${[['Sakit','sakit'],['Izin','izin'],['Alpha','alpa']].map((x,i)=>`<tr><td>${i+1}</td><td class="l">${x[0]}</td>${hd(x[1])}</tr>`).join('')}</table>`:'',
nkH=o.naik?`${fh('F. KENAIKAN KELAS')}${fr('','Keputusan','Berdasarkan Hasil Belajar Semester I dan II, Tahun Ajaran '+ta,1)}<div class="fr in"><span></span><span>Peserta Didik ditetapkan</span><span>: ${ch.map(x=>x==pick?`<b>${x}</b>`:`<s>${x}</s>`).join(' / ')}</span></div>${fr('','Dari',xii?S.school.toUpperCase().replace(' NGANJUK',''):'Kelas '+k+' Ke Kelas '+(r.kls_ke||nextK(k)||'-'),1)}${fr('','Tanggal',tgi(r.tgl_naik),1)}<div class="ttd" style="margin-top:40px"><div>Wali Kelas,<br><br><br><br><u>${E(r.wk_nama||'..................')}</u><br>NIP. ${E(r.wk_nip||'')}</div>${xii?`<div>Mengetahui,<br>Kepala Sekolah,<br><br><br><u>${E(S.sc.kepsek)}</u><br>NIP. ${E(S.sc.nipk)}</div>`:''}</div>`:'';
const ttl=(o.nilai&&o.hadir&&o.ekskul&&o.naik)?'II. LAPORAN HASIL CAPAIAN PEMBELAJARAN':'II. LAPORAN HASIL CAPAIAN PEMBELAJARAN'+(!o.nilai&&!o.naik&&o.ekskul&&!o.hadir?' · EKSTRAKURIKULER':!o.nilai&&!o.naik&&!o.ekskul&&o.hadir?' · KEHADIRAN & KOKURIKULER':o.nilai&&!o.hadir&&!o.ekskul&&!o.naik?' · NILAI':'');
const a=`<div class="pg dc"><div class="ptt" style="text-align:left">${ttl}<br>&nbsp;&nbsp;&nbsp;&nbsp;PESERTA DIDIK TAHUN AJARAN ${ta}${ms.length==1?' · SEMESTER '+sl(ms[0]):''}</div>${idn}${nilaiH}${kokH}</div>`,rest=ekH+hdH+nkH;
return a+(rest?`<div class="pg dc">${rest}</div>`:'')}

function pdfDoc(s,o){let h='';if(o.bio)h+=reg(s);if(o.nilai||o.hadir||o.ekskul||o.naik){const all=[...new Set(db.siswa.filter(x=>x.nisn==s.nisn).map(x=>x.ta))].sort(),tas=o.ta=='Semua'?all:all.filter(t=>t==o.ta);tas.forEach(t=>h+=lap(s,t,o));if(!tas.length)h+=`<div class="pg">${E(s.nama)} tidak terdaftar pada tahun ajaran ${E(o.ta)}. Pilih tahun ajaran lain atau “Semua”.</div>`}return h||'<div class="pg">Tidak ada isi dipilih</div>'}
