/* ===== Import DATABASE_SISWA.xlsx (sheet PesertaDidik + Kontrol Induk), dibaca per posisi kolom ===== */
const CI=a=>[...a].reduce((n,c)=>n*26+c.charCodeAt(0)-64,0)-1,RMAP={C:'nis',D:'nama',E:'panggilan',F:'nisn',G:'jk',H:'tmp',I:'tgl',J:'agama',K:'kewarganegaraan',L:'nik',M:'anak_ke',N:'jml_saudara',O:'yatim',P:'bahasa',Q:'alamat',R:'rt_rw',S:'kelurahan',T:'kecamatan',U:'kab',V:'prov',W:'kodepos',X:'hp',Y:'tinggal',Z:'jarak',AA:'gol_darah',AB:'penyakit',AC:'kelainan',AD:'tinggi',AE:'berat',AF:'asal',AG:'tgl_ijazah_smp',AH:'no_ijazah_smp',AI:'lama',AJ:'masuk',AK:'sekolah_pindah',AL:'alasan_pindah',AM:'kelas_masuk',AN:'rombel_masuk',AO:'tgl_masuk',AP:'ayah',AQ:'agama_ayah',AR:'wn_ayah',AS:'pend_ayah',AT:'kerja_ayah',AU:'gaji_ayah',AV:'hp_ayah',AW:'ket_ayah',AX:'ibu',AY:'agama_ibu',AZ:'wn_ibu',BA:'pend_ibu',BB:'kerja_ibu',BC:'gaji_ibu',BD:'hp_ibu',BE:'ket_ibu',BF:'al_jalan',BG:'al_rt',BH:'al_desa',BI:'al_kec',BJ:'al_kab',BK:'al_prov',BL:'al_pos',BM:'wali',BN:'agama_wali',BO:'wn_wali',BP:'pend_wali',BQ:'kerja_wali',BR:'gaji_wali',BS:'hp_wali',BT:'ket_wali',BU:'alw_jalan',BV:'alw_rt',BW:'alw_desa',BX:'alw_kec',BY:'alw_kab',BZ:'alw_prov',CA:'alw_pos',CD:'nopes'},KMAP={I:'alasan_keluar',J:'tgl_keluar',K:'kelas_keluar',L:'tujuan',M:'nopes',N:'no_skl',O:'no_ijazah_sma',P:'tgl_ijazah_sma',Q:'no_transkrip'},
iso=v=>typeof v=='number'?new Date(Math.round((v-25569)*864e5)).toISOString().slice(0,10):v,cl=v=>typeof v=='string'?v.trim():v;
function realRows(w){const rd=n=>w.Sheets[n]?XLSX.utils.sheet_to_json(w.Sheets[n],{header:1,defval:''}):[],km={};rd('Kontrol Induk').slice(5).forEach(r=>{if(r[2]!=='')km[String(r[2]).trim()]=r});const out=[];
rd('PesertaDidik').slice(5).forEach(r=>{if(!cl(r[CI('D')])||r[CI('C')]==='')return;const o={};for(const[c,k]of Object.entries(RMAP)){let v=cl(r[CI(c)]);if((k=='tgl'||k=='tgl_masuk'||k=='tgl_ijazah_smp')&&typeof v=='number')v=iso(v);o[k]=v===''?'-':v}
o.nis=String(o.nis);o.nisn=String(r[CI('F')]).trim();o.jk=/^p/i.test(o.jk)?'P':'L';o.kelas=(o.kelas_masuk||'')+'-'+(o.rombel_masuk||'');const q=km[o.nis];
if(q){for(const[c,k]of Object.entries(KMAP)){let v=cl(q[CI(c)]);if(typeof v=='number'&&k.startsWith('tgl'))v=iso(v);o[k]=v===''?'-':v}o.kelas=q[CI('K')]||o.kelas}
o.status=o.alasan_keluar=='Lulus'?'Lulus':'Aktif';if(o.tgl_keluar&&o.tgl_keluar!='-')o.thn_lulus=+String(o.tgl_keluar).slice(0,4);out.push(o)});return out}
