function pager(key,list){const n=list.length,pz=S.psz,tp=Math.max(1,Math.ceil(n/pz));let p=Math.min(Math.max(1,S.pn[key]||1),tp);S.pn[key]=p;(S.pt=S.pt||{})[key]=tp;const ui=n>pz||pz!=25?`<div class="pgn"><span>${n?(p-1)*pz+1:0}–${Math.min(n,p*pz)} dari ${n}</span>${B('pgo',key+'|'+(p-1),'‹',p>1?'o':'o')}<b>Hal ${p}/${tp}</b>${B('pgo',key+'|'+(p+1),'›')}<select data-c="psz">${opt([10,25,50,100],pz)}</select></div>`:'';return{rows:list.slice((p-1)*pz,p*pz),ui,total:n,start:(p-1)*pz}}
