/* ===== Master kelas & mapel ===== */
function applyMaster(){const M=db.master=db.master||{kelas:[],mapel:[]};M.kelas.forEach(k=>{if(!K.includes(k))K.push(k)});M.mapel.forEach(m=>{if(SC.includes(m.kode))return;SUB.push([m.kode,m.nama]);SC.push(m.kode);SN[m.kode]=m.nama;RF.nilai.push([m.kode,m.nama+' (kosong = X)','n']);CFG.nilai.c.push(m.kode);m.tingkat.forEach(t=>{const g=(LYT[t]||[])[0];if(g&&!g[1].includes(m.kode))g[1].push(m.kode)})})}
function unMapel(c){const i=SUB.findIndex(m=>m[0]==c);if(i>=0)SUB.splice(i,1);const j=SC.indexOf(c);if(j>=0)SC.splice(j,1);delete SN[c];const r=RF.nilai.findIndex(f=>f[0]==c);if(r>=0)RF.nilai.splice(r,1);const q=CFG.nilai.c.indexOf(c);if(q>=0)CFG.nilai.c.splice(q,1);Object.values(LYT).forEach(g=>g.forEach(([,cs])=>{const z=cs.indexOf(c);if(z>=0)cs.splice(z,1)}))}
const tkOf=c=>['X','XI','XII'].filter(t=>(LYT[t]||[]).some(([,cs])=>cs.includes(c))).join(', ')||'-';
function masterPg(){const M=db.master,kk=kls(),usedK=k=>db.siswa.some(x=>x.kelas==k||x.kls_ke==k)||db.guru.some(g=>g.wali==k||(g.kelasAjar||[]).includes(k)),usedM=c=>db.nilai.some(n=>num(n[c]))||db.guru.some(g=>g.mapel.includes(c));
return`<h2>Master Kelas & Mapel</h2><p class="sub">Daftar ini menjadi tabel <code>kelas</code> dan <code>mapel</code>. Kelas dan mapel baru langsung dipakai di seluruh aplikasi (filter, editor nilai, import, PDF). Hanya yang ditambahkan di sini yang bisa dihapus, dan hanya bila belum dipakai.</p><div class="g g2"><div class="card"><h3>Kelas / rombel</h3><div class="bar" style="flex-wrap:wrap">${kk.map(k=>bd(k)+(M.kelas.includes(k)&&!usedK(k)?B('mkdel',k,'🗑','x'):'')).join(' ')}</div><div class="bar" style="margin-top:12px"><input id="mk" placeholder="mis. X-2, XI-3, XII-2" style="flex:1">${B('mkadd','','Tambah kelas','a')}</div></div><div class="card"><h3>Mata pelajaran</h3><div class="tw" style="max-height:260px">${tbl(['Kode','Nama','Tingkat',''],SUB.map(m=>['<code>'+m[0]+'</code>',E(m[1]),tkOf(m[0]),M.mapel.some(x=>x.kode==m[0])&&!usedM(m[0])?B('mpdel',m[0],'🗑','x'):'']))}</div><div class="fl" style="grid-template-columns:1fr 2fr;margin-top:10px"><div><label>Kode (3 huruf)</label><input id="mpk" maxlength="3"></div><div><label>Nama mapel</label><input id="mpn"></div></div><div class="bar" style="margin-top:8px">${['X','XI','XII'].map(t=>`<label style="display:flex;gap:4px;margin:0"><input type="checkbox" class="mpt" value="${t}"> ${t}</label>`).join('')}<span class="sp"></span>${B('mpadd','','Tambah mapel','a')}</div></div></div>`}
A.mkadd=()=>{const k=$('#mk').value.trim().toUpperCase();if(!/^(XII|XI|X)-\d+$/.test(k))return toast('Format kelas: X-2, XI-3, XII-2');if(kls().includes(k))return toast('Kelas '+k+' sudah ada');db.master.kelas.push(k);applyMaster();L('Tambah kelas '+k);R();toast('Kelas '+k+' ditambahkan')};
A.mkdel=v=>{db.master.kelas=db.master.kelas.filter(k=>k!=v);const i=K.indexOf(v);if(i>=0)K.splice(i,1);L('Hapus kelas '+v);R()};
A.mpadd=()=>{const c=$('#mpk').value.trim().toLowerCase(),n=$('#mpn').value.trim(),t=[...document.querySelectorAll('.mpt:checked')].map(e=>e.value);if(!/^[a-z]{3}$/.test(c)||c=='sem')return toast('Kode harus 3 huruf (bukan "sem")');if(SC.includes(c))return toast('Kode '+c+' sudah dipakai');if(!n)return toast('Isi nama mapel');if(!t.length)return toast('Pilih minimal satu tingkat');db.master.mapel.push({kode:c,nama:n,tingkat:t});applyMaster();L('Tambah mapel '+n);R();toast('Mapel '+n+' ditambahkan')};
