function regExtra(t,k,l,save){const M=db.master=db.master||{kelas:[],mapel:[]};M.extra=M.extra||{};const A_=M.extra[t]=M.extra[t]||[];if(save&&!A_.some(x=>x.k==k))A_.push({k,l});
if(t=='siswa'){let g=FD.find(x=>x[2]=='extra');if(!g){g=['Data tambahan (dari Excel)',[],'extra'];FD.push(g)}if(!FK.includes(k)){g[1].push(k+'|'+l);FK.push(k);CFG.siswa.c.push(k)}FL[k]=l;_am=null}
else{if(!CFG[t].c.includes(k))CFG[t].c.push(k);if(!RF[t].some(f=>f[0]==k))RF[t].push([k,l]);SN[k]=l}}
function xcode(h,t,newX){const q=nz(h),M=(db.master&&db.master.extra&&db.master.extra[t])||[],e=M.find(x=>nz(x.l)==q)||newX.find(x=>x.t==t&&nz(x.l)==q);if(e)return e.k;
const used=new Set([...FK,...(RF[t]||[]).map(f=>f[0]),...M.map(x=>x.k),...newX.map(x=>x.k)]),b='x_'+(q.replace(/ /g,'_').slice(0,24)||'kolom');let c=b,n=2;while(used.has(c))c=b+'_'+n++;newX.push({t,k:c,l:String(h).trim()});return c}
function assignX(z,pt){const ty=k=>!k||k=='x'?'':k.startsWith('m:')||k=='new'||k=='mapelcol'||k=='nilaicol'?'nilai':['sakit','izin','alpa','kokur'].includes(k)?'hadir':['ekskul','predikat'].includes(k)?'ekskul':FK.includes(k)?'siswa':'',ty2=j=>{const m=z.map[j];return m=='x'?z.xt[j]:m=='new'?'nilai':ty(m)},n=z.heads.length,single=z.ts.length==1?z.ts[0]:'';z.xt={};
for(let i=0;i<n;i++){const h=z.heads[i];if(!h||(z.map[i]&&z.map[i]!='x'&&z.map[i]!='new'))continue;const vals=z.aoa.slice(z.hr+1).map(r=>String(r[i]??'').trim()).filter(x=>x!==''&&x.toUpperCase()!='X');if(!vals.length){z.map[i]='';continue}
const b=z.base[i]||h,nb=nz(b);if(/^((no|nomor)( urut)?|(jumlah|total|rata|ranking|rank|peringkat|kkm|kktp|absen|urut)\b.*)$/.test(nb)){z.map[i]='';continue}
let T=/terlambat|dispensasi|bolos|cuti|hadir/.test(nb)?'hadir':/ekskul|ekstra|pramuka|organisasi/.test(nb)?'ekskul':'';
for(let d=1;d<n&&!T;d++)T=(i-d>=0?ty2(i-d):'')||(i+d<n?ty2(i+d):'');T=T||single||pt;z.xt[i]=T;
const nn=x=>+x.replace(',','.');z.map[i]=(T=='nilai'&&vals.filter(x=>!isNaN(nn(x))&&nn(x)>=0&&nn(x)<=100).length>=vals.length*.8)?'new':'x'}}
const XL=t=>((db.master.extra||{})[t]||[]).map(x=>x.l),XV=(x,t)=>((db.master.extra||{})[t]||[]).map(e=>E(x[e.k]??'')),
xsec=s=>{const X=((db.master.extra||{}).siswa||[]).filter(x=>s[x.k]!=null&&s[x.k]!=='');return X.length?fh('J. KETERANGAN TAMBAHAN')+X.map((x,i)=>fr((i+1)+'.',x.l,s[x.k])).join(''):''};

